"use client"

// Bollard UI — shortcut-recorder · MIT licence · https://bollard-ui.vercel.app/components/shortcut-recorder

import * as React from "react"
import { CircleX, TriangleAlert, X } from "lucide-react"

import { cn } from "@/lib/utils"
import {
  checkShortcut,
  detectPlatform,
  formatShortcut,
  isModifierKey,
  shortcutFromEvent,
  type Platform,
  type ShortcutBinding,
  type ShortcutIssue,
} from "./shortcut-rules"

export { checkShortcut, detectPlatform, formatShortcut, resolveShortcut, shortcutFromEvent } from "./shortcut-rules"
export type { Platform, ShortcutBinding, ShortcutIssue, ShortcutProblem } from "./shortcut-rules"

export interface ShortcutRecorderProps
  extends Omit<React.ComponentProps<"div">, "defaultValue" | "onChange"> {
  /** Visible label. */
  label?: string
  /** Controlled shortcut in canonical form ("Mod+Shift+K"), or null for none. */
  value?: string | null
  /** Initial shortcut when uncontrolled. */
  defaultValue?: string | null
  /** Called with the saved shortcut, or null when cleared. */
  onValueChange?: (value: string | null) => void
  /** The app's existing shortcuts; a clash names the action. Leave out the one being edited. */
  bindings?: ShortcutBinding[]
  /** Platform to read back first. Detected from the browser when left out. */
  platform?: Platform
  /** Shown while empty. */
  placeholder?: string
  /** Shown while recording with nothing held. */
  recordingLabel?: string
  /** Hint while recording. */
  recordingHint?: string
  /** Saves a shortcut that only has warnings. */
  useAnywayLabel?: string
  /** Label of the try-again button after a blocked combo. */
  tryAgainLabel?: string
  /** Accessible label of the clear button. */
  clearLabel?: string
  /** Platform names in the readback. */
  macLabel?: string
  /** Label for the Windows/Linux read-back. */
  pcLabel?: string
  /** Rewrites an issue's text, e.g. to translate it. `issue.problem` says which check fired; `keys` is the canonical shortcut. */
  formatIssue?: (issue: ShortcutIssue, keys: string) => string
}

const fixClass =
  "inline-flex h-6 items-center gap-1 rounded-md border border-amber-500/40 px-2 font-medium text-amber-900 transition-colors hover:bg-amber-500/10 dark:text-amber-200 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
const linkClass = "h-6 rounded-md px-1.5 font-medium underline-offset-2 hover:underline outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
const keyframes = `@keyframes cui-shortcut-recorder-pop{0%{transform:scale(.88);opacity:.4}100%{transform:none;opacity:1}}`

function Kbd({ children, className }: { children: React.ReactNode; className?: string }) {
  return <kbd className={cn("inline-flex h-6 items-center rounded border bg-muted px-1.5 font-sans text-xs font-medium text-foreground shadow-[inset_0_-1px_0] shadow-border", className)}>{children}</kbd>
}

/**
 * Records a keyboard shortcut and catches the ones that will never fire or will hurt someone:
 * combos the browser keeps (Ctrl+W, ⌘Q, Ctrl+T) on any platform, not just the one you're on,
 * clashes with the app's own bindings, Ctrl+Alt (AltGr on European layouts), punctuation that
 * needs AltGr elsewhere, and plain keys that fire while typing. It reads the result back for
 * Mac and Windows/Linux, so ⌘ and Ctrl are never confused. Tab still leaves; Esc cancels.
 */
export function ShortcutRecorder({
  label = "Shortcut",
  value,
  defaultValue = null,
  onValueChange,
  bindings = [],
  platform: platformProp,
  placeholder = "Click to record",
  recordingLabel = "Press a shortcut…",
  recordingHint = "Esc cancels · Backspace clears",
  useAnywayLabel = "Use anyway",
  tryAgainLabel = "Try again",
  clearLabel = "Clear shortcut",
  macLabel = "Mac",
  pcLabel = "Windows/Linux",
  formatIssue,
  className,
  ...props
}: ShortcutRecorderProps) {
  const [inner, setInner] = React.useState(defaultValue)
  const [detected, setDetected] = React.useState<Platform>("windows")
  const [recording, setRecording] = React.useState(false)
  const [held, setHeld] = React.useState("")
  const [candidate, setCandidate] = React.useState<{ keys: string; issues: ShortcutIssue[] } | null>(null)
  const recorderRef = React.useRef<HTMLButtonElement>(null)
  const labelId = React.useId()
  const current = value === undefined ? inner : value
  const platform = platformProp ?? detected
  const pcPlatform = platform === "mac" ? "windows" : platform

  React.useEffect(() => setDetected(detectPlatform()), [])

  const commit = (next: string | null) => {
    if (value === undefined) setInner(next)
    onValueChange?.(next)
    setCandidate(null)
  }
  const start = () => {
    setCandidate(null)
    setHeld("")
    setRecording(true)
    recorderRef.current?.focus()
  }

  const onKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>) => {
    if (!recording || event.repeat) return
    const bare = !event.ctrlKey && !event.metaKey && !event.altKey
    if (event.key === "Tab" && bare) return setRecording(false)
    event.preventDefault()
    if (bare && !event.shiftKey && event.key === "Escape") return setRecording(false)
    if (bare && !event.shiftKey && (event.key === "Backspace" || event.key === "Delete")) {
      setRecording(false)
      return commit(null)
    }
    if (isModifierKey(event.key)) {
      const mods = platform === "mac"
        ? [event.ctrlKey && "⌃", event.altKey && "⌥", event.shiftKey && "⇧", event.metaKey && "⌘"].filter(Boolean).join("")
        : [event.ctrlKey && "Ctrl", event.metaKey && "Win", event.altKey && "Alt", event.shiftKey && "Shift", ""].filter((m) => m !== false).join("+")
      return setHeld(mods === "+" ? "" : mods)
    }
    const keys = shortcutFromEvent(event, platform)
    if (!keys) return
    setRecording(false)
    const issues = checkShortcut(keys, bindings, event.getModifierState?.("AltGraph"))
    if (issues.length) setCandidate({ keys, issues })
    else commit(keys)
  }

  const savedIssues = React.useMemo(() => (current ? checkShortcut(current, bindings) : []), [current, bindings])
  const shownKeys = candidate?.keys ?? current
  const issues = (candidate?.issues ?? savedIssues).map((issue) =>
    formatIssue && shownKeys ? { ...issue, message: formatIssue(issue, shownKeys) } : issue,
  )
  const blocking = issues.filter((issue) => issue.blocking)

  return (
    <div data-slot="shortcut-recorder" className={cn("grid w-full max-w-xs gap-1.5", className)} {...props}>
      <style>{keyframes}</style>
      <span id={labelId} className="w-fit text-sm font-medium">{label}</span>
      <div className="flex gap-2">
        <button
          ref={recorderRef}
          type="button"
          aria-labelledby={labelId}
          aria-pressed={recording}
          aria-describedby={`${labelId}-status`}
          data-recording={recording ? "" : undefined}
          data-warning={issues.length && !blocking.length ? "" : undefined}
          data-danger={blocking.length ? "" : undefined}
          onClick={() => (recording ? setRecording(false) : start())}
          onKeyDown={onKeyDown}
          onKeyUp={(event) => recording && isModifierKey(event.key) && setHeld("")}
          onBlur={() => setRecording(false)}
          className="flex h-9 min-w-0 flex-1 items-center gap-2 rounded-md border bg-transparent px-3 text-left text-sm shadow-xs transition-[color,box-shadow,border-color] outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 dark:bg-input/30 data-recording:border-ring data-recording:ring-[3px] data-recording:ring-ring/50 data-warning:border-amber-500 dark:data-warning:border-amber-400 data-danger:border-red-500 dark:data-danger:border-red-400"
        >
          {recording ? (
            <>
              <span aria-hidden className="size-2 shrink-0 rounded-full bg-red-500 motion-safe:animate-pulse" />
              {held ? <Kbd>{held}</Kbd> : <span className="text-muted-foreground">{recordingLabel}</span>}
            </>
          ) : shownKeys ? (
            <Kbd key={shownKeys} className={cn("motion-safe:animate-[cui-shortcut-recorder-pop_200ms_ease-out]", blocking.length && "line-through decoration-red-500")}>
              {formatShortcut(shownKeys, platform)}
            </Kbd>
          ) : (
            <span className="text-muted-foreground">{placeholder}</span>
          )}
        </button>
        {current && !recording && !candidate && !issues.length ? (
          <button type="button" aria-label={clearLabel} onClick={() => commit(null)} className="inline-flex size-9 shrink-0 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-foreground outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50">
            <X aria-hidden className="size-4" />
          </button>
        ) : null}
      </div>
      <div id={`${labelId}-status`} aria-live="polite" className="grid gap-1.5 text-xs">
        {recording ? (
          <p className="mt-1.5 text-muted-foreground">{recordingHint}</p>
        ) : shownKeys ? (
          <p className="mt-1.5 flex flex-wrap gap-x-3 gap-y-1 text-muted-foreground">
            {(platform === "mac" ? (["mac", pcPlatform] as const) : ([pcPlatform, "mac"] as const)).map((p, i) => (
              <span key={p} className={cn(i === 0 && "text-foreground")}>
                {p === "mac" ? macLabel : pcLabel} <span className="font-medium">{formatShortcut(shownKeys, p)}</span>
              </span>
            ))}
          </p>
        ) : null}
        {recording ? null : blocking.length ? (
          <div role="alert" className="flex gap-1.5 text-red-700 dark:text-red-400">
            <span className="flex h-6 shrink-0 items-center"><CircleX aria-hidden className="size-3.5" /></span>
            <span className="flex min-w-0 flex-wrap items-center gap-x-2">
              <span className="py-1">{blocking[0].message}</span>
              <button type="button" onClick={start} className={linkClass}>{tryAgainLabel}</button>
            </span>
          </div>
        ) : issues.length ? (
          <div className="grid gap-1 text-amber-700 dark:text-amber-400">
            {issues.map((issue, index) => (
              <p key={`${issue.problem}-${index}`} className="flex gap-1.5">
                <span className="flex h-5 shrink-0 items-center"><TriangleAlert aria-hidden className="size-3.5" /></span>
                <span className="py-0.5">{issue.message}</span>
              </p>
            ))}
            <span className="flex flex-wrap items-center gap-2 pl-5">
              {candidate ? <button type="button" onClick={() => commit(candidate.keys)} className={fixClass}>{useAnywayLabel}</button> : null}
              <button type="button" onClick={start} className={linkClass}>{tryAgainLabel}</button>
            </span>
          </div>
        ) : null}
      </div>
    </div>
  )
}

// Bollard UI — shortcut-recorder · MIT licence · https://bollard-ui.vercel.app/components/shortcut-recorder

/**
 * Shortcuts are stored platform-neutral: `Mod` is ⌘ on Mac and Ctrl elsewhere, `Ctrl` is the
 * Mac ⌃ key, then `Alt`, `Shift` and the key, e.g. "Mod+Shift+K".
 */
export type Platform = "mac" | "windows" | "linux"

export interface ShortcutBinding {
  /** Canonical shortcut, e.g. "Mod+K". */
  keys: string
  /** What it does, e.g. "Open search". */
  action: string
}

export type ShortcutProblem = "reserved" | "browser" | "app" | "altgr" | "layout" | "option" | "no-modifier"

export interface ShortcutIssue {
  problem: ShortcutProblem
  message: string
  /** Blocking issues can't be saved: the browser or OS never hands that key to the page. */
  blocking: boolean
}

const PLATFORMS: Platform[] = ["mac", "windows", "linux"]

/** Combos the browser or OS keeps for itself, in resolved form (Ctrl, Meta, Alt, Shift, key). */
const RESERVED: Record<"mac" | "pc", Record<string, string>> = {
  mac: {
    "Meta+W": "closes the tab", "Meta+T": "opens a new tab", "Meta+N": "opens a new window", "Meta+Q": "quits the browser",
    "Meta+Shift+N": "opens a private window", "Meta+Shift+T": "reopens a closed tab", "Meta+Shift+W": "closes the window",
    "Meta+H": "hides the browser", "Meta+M": "minimizes the window", "Meta+Tab": "switches apps", "Meta+Space": "opens Spotlight",
    "Ctrl+Space": "switches input source", "Meta+`": "switches windows", "Meta+Shift+3": "takes a screenshot",
    "Meta+Shift+4": "takes a screenshot", "Meta+Shift+5": "opens screenshot tools", "Ctrl+Tab": "switches tabs",
    "Ctrl+Shift+Tab": "switches tabs", "Meta+Alt+Escape": "opens Force Quit", "Ctrl+↑": "opens Mission Control",
    "Ctrl+←": "switches desktops", "Ctrl+→": "switches desktops",
  },
  pc: {
    "Ctrl+W": "closes the tab", "Ctrl+T": "opens a new tab", "Ctrl+N": "opens a new window", "Ctrl+Shift+N": "opens a private window",
    "Ctrl+Shift+T": "reopens a closed tab", "Ctrl+Shift+W": "closes the window", "Ctrl+Shift+Q": "quits the browser",
    "Ctrl+Tab": "switches tabs", "Ctrl+Shift+Tab": "switches tabs", "Ctrl+PageUp": "switches tabs", "Ctrl+PageDown": "switches tabs",
    "Alt+F4": "closes the window", "Alt+Tab": "switches apps", "Ctrl+Alt+Delete": "opens the security screen",
  },
}
/** Combos the page can take over, but users expect the browser's meaning. */
const FAMILIAR: Record<string, string> = {
  S: "Save page", P: "Print", F: "Find", R: "Reload", L: "the address bar", D: "Bookmark", C: "Copy", V: "Paste",
  X: "Cut", Z: "Undo", A: "Select all", "Shift+I": "developer tools", "0": "reset zoom", "=": "zoom in", "-": "zoom out",
}
/** Keys that need AltGr or Shift on German, French or Nordic layouts. */
const LAYOUT_KEYS: Record<string, string> = {
  "[": "AltGr+8 on German keyboards", "]": "AltGr+9 on German keyboards", "\\": "AltGr+ß on German keyboards",
  "/": "Shift+7 on German keyboards", ";": "Shift+, on German keyboards", "'": "Shift+# on German keyboards",
  "`": "a dead key on German and French keyboards", "=": "Shift+0 on German keyboards",
}

const CODE_NAMES: Record<string, string> = {
  BracketLeft: "[", BracketRight: "]", Backslash: "\\", Slash: "/", Semicolon: ";", Quote: "'", Backquote: "`",
  Equal: "=", Minus: "-", Comma: ",", Period: ".", ArrowUp: "↑", ArrowDown: "↓", ArrowLeft: "←", ArrowRight: "→",
}
const MODIFIER_KEYS = ["Control", "Shift", "Alt", "Meta", "AltGraph", "OS", "CapsLock", "Fn"]

/** Detects the platform from the browser. Call it in an effect, never during render. */
export function detectPlatform(): Platform {
  const ua = navigator.userAgent
  return /Mac|iPhone|iPad/.test(ua) ? "mac" : /Win/.test(ua) ? "windows" : "linux"
}

export const isModifierKey = (key: string) => MODIFIER_KEYS.includes(key)

/** Turns a keydown into the canonical form, or null while only modifiers are held. */
export function shortcutFromEvent(event: Pick<KeyboardEvent, "key" | "code" | "ctrlKey" | "metaKey" | "altKey" | "shiftKey">, platform: Platform) {
  if (isModifierKey(event.key)) return null
  const key = /^Key[A-Z]$/.test(event.code) ? (/^[a-z]$/i.test(event.key) ? event.key.toUpperCase() : event.code.slice(3))
    : /^Digit\d$/.test(event.code) ? event.code.slice(5)
    : CODE_NAMES[event.code] ?? (event.key === " " ? "Space" : event.key.length === 1 ? event.key.toUpperCase() : event.key)
  const mac = platform === "mac"
  return [
    (mac ? event.metaKey : event.ctrlKey) && "Mod",
    (mac ? event.ctrlKey : event.metaKey) && (mac ? "Ctrl" : "Meta"),
    event.altKey && "Alt",
    event.shiftKey && "Shift",
    key,
  ].filter(Boolean).join("+")
}

/** The physical keys a canonical shortcut means on one platform: Ctrl, Meta, Alt, Shift, then the key. */
export function resolveShortcut(keys: string, platform: Platform) {
  const parts = keys.split("+")
  const key = parts.pop() || "+"
  const has = (m: string) => parts.includes(m)
  const mac = platform === "mac"
  const ctrl = mac ? has("Ctrl") : has("Mod") || has("Ctrl")
  const meta = mac ? has("Mod") || has("Meta") : has("Meta") || (has("Mod") && has("Ctrl"))
  return [ctrl && "Ctrl", meta && "Meta", has("Alt") && "Alt", has("Shift") && "Shift", key].filter(Boolean).join("+")
}

/** How the shortcut reads on a platform: ⌃⌥⇧⌘K on Mac, Ctrl+Alt+Shift+K on Windows, Super on Linux. */
export function formatShortcut(keys: string, platform: Platform) {
  const parts = resolveShortcut(keys, platform).split("+")
  if (platform === "mac") {
    const symbols: Record<string, string> = { Ctrl: "⌃", Alt: "⌥", Shift: "⇧", Meta: "⌘", Escape: "⎋", Enter: "↩", Backspace: "⌫", Delete: "⌦", Tab: "⇥" }
    return ["Ctrl", "Alt", "Shift", "Meta"].filter((m) => parts.includes(m)).map((m) => symbols[m]).join("") + (symbols[parts[parts.length - 1]] ?? parts[parts.length - 1])
  }
  return parts.map((p) => (p === "Meta" ? (platform === "windows" ? "Win" : "Super") : p)).join("+")
}

/**
 * Everything wrong with a shortcut on any platform it will run on: combos the browser or OS
 * never hands to the page (blocking), familiar browser commands it would take over, clashes
 * with the app's own bindings, Ctrl+Alt (which is AltGr on European layouts), punctuation that
 * needs AltGr on other layouts, Mac ⌥+letter, and plain keys that would fire while typing.
 */
export function checkShortcut(keys: string, bindings: ShortcutBinding[] = [], altGraph = false): ShortcutIssue[] {
  const issues: ShortcutIssue[] = []
  const key = keys.split("+").pop()!
  const mods = keys.split("+").slice(0, -1)
  const onMac = RESERVED.mac[resolveShortcut(keys, "mac")]
  const onPc = RESERVED.pc[resolveShortcut(keys, "windows")]
  const hits = onMac && onMac === onPc ? [`it ${onMac}`]
    : [onMac && `on Mac it ${onMac}`, onPc && `on Windows and Linux it ${onPc}`].filter((hit): hit is string => !!hit)
  if (hits.length) issues.push({ problem: "reserved", blocking: true, message: `Browsers keep this for themselves: ${hits.join(", and ")}.` })
  const onWindows = resolveShortcut(keys, "windows").split("+")
  if (onWindows.includes("Meta")) issues.push({ problem: "reserved", blocking: true, message: "On Windows this needs the Windows key, which belongs to the operating system." })
  if (!hits.length && mods.length === 1 && mods[0] === "Mod" && FAMILIAR[key])
    issues.push({ problem: "browser", blocking: false, message: `Replaces the browser's ${FAMILIAR[key]}, which people expect here.` })
  if (!hits.length && mods.join("+") === "Mod+Shift" && FAMILIAR[`Shift+${key}`])
    issues.push({ problem: "browser", blocking: false, message: `Replaces the browser's ${FAMILIAR[`Shift+${key}`]}.` })
  const clash = bindings.find((b) => PLATFORMS.some((p) => resolveShortcut(b.keys, p) === resolveShortcut(keys, p)))
  if (clash) issues.push({ problem: "app", blocking: false, message: `Already used for “${clash.action}”.` })
  if (altGraph) issues.push({ problem: "altgr", blocking: false, message: "Your layout needs AltGr for this key, so it may not work as recorded." })
  else if (onWindows.includes("Ctrl") && onWindows.includes("Alt") && !onWindows.includes("Meta"))
    issues.push({ problem: "altgr", blocking: false, message: `Ctrl+Alt is AltGr on many European layouts, so on Windows it can type a character instead (AltGr+E is €).` })
  if (LAYOUT_KEYS[key]) issues.push({ problem: "layout", blocking: false, message: `${key} is ${LAYOUT_KEYS[key]}, so some people can't press this.` })
  if (mods.join("+") === "Alt" && /^[A-Z]$/.test(key))
    issues.push({ problem: "option", blocking: false, message: `On Mac, ⌥${key} types a special character in text fields.` })
  if (!mods.some((m) => m !== "Shift") && /^[A-Z0-9]$|^Space$/.test(key))
    issues.push({ problem: "no-modifier", blocking: false, message: "With no modifier, this fires while people type." })
  return issues
}
